@Composable
internal fun ViewMenuIcon(name: String, tint: Color, size: Dp, modifier: Modifier = Modifier) {
    val vector = remember(name) { FolioGlassIcons.resolve(name) }
    Image(vector, null, modifier.size(size), colorFilter = ColorFilter.tint(tint))
}
